import logging
import traceback

from django.core.exceptions import PermissionDenied
from django.http import Http404
from django.utils.translation import gettext_lazy as _
from rest_framework import exceptions
from rest_framework.response import Response
from rest_framework.views import exception_handler

logger = logging.getLogger(__name__)


def custom_exception_handler(exc, context):
    response = exception_handler(exc, context)

    if response is not None:
        custom_response_data = {
            "success": False,
            "error": {
                "code": response.status_code,
                "message": _format_error_message(response.data),
                "details": response.data if isinstance(response.data, dict) else None,
            },
        }
        response.data = custom_response_data
        return response

    if isinstance(exc, Http404):
        return Response(
            {
                "success": False,
                "error": {
                    "code": 404,
                    "message": _("Not found"),
                    "details": str(exc),
                },
            },
            status=404,
        )

    if isinstance(exc, PermissionDenied):
        return Response(
            {
                "success": False,
                "error": {
                    "code": 403,
                    "message": _("Permission denied"),
                    "details": str(exc),
                },
            },
            status=403,
        )

    if isinstance(exc, exceptions.ValidationError):
        return Response(
            {
                "success": False,
                "error": {
                    "code": 400,
                    "message": _("Validation error"),
                    "details": exc.detail,
                },
            },
            status=400,
        )

    logger.error(
        "Unhandled exception: %s\n%s",
        exc,
        traceback.format_exc(),
        extra={"request": context.get("request")},
    )

    return Response(
        {
            "success": False,
            "error": {
                "code": 500,
                "message": _("Internal server error"),
                "details": str(exc) if settings.DEBUG else None,
            },
        },
        status=500,
    )


def _format_error_message(data):
    if isinstance(data, dict):
        if "detail" in data:
            return str(data["detail"])
        if "non_field_errors" in data:
            return " ".join(str(e) for e in data["non_field_errors"])
        messages = []
        for key, value in data.items():
            if isinstance(value, list):
                messages.append(f"{key}: {', '.join(str(v) for v in value)}")
            else:
                messages.append(f"{key}: {value}")
        return " | ".join(messages) if messages else "Validation error"
    if isinstance(data, list):
        return " | ".join(str(item) for item in data)
    return str(data)


